37. // ErrUnsupportedSigningKey is returned when an unsupported private key is used to sign. Currently only ecdsa and rsa keys are supported
38. var ErrUnsupportedSigningKey = errors.New("signing key algorithm not supported")
39. 
40. var supportedAlgorithms = []jwa.SignatureAlgorithm{jwa.PS256, jwa.PS384, jwa.PS512, jwa.ES256, jwa.ES384, jwa.ES512}
41. 
42. func isAlgorithmSupported(alg jwa.SignatureAlgorithm) bool {
43. 	for _, curr := range supportedAlgorithms {
44. 		if curr == alg {
45. 			return true
46. 		}
47. 	}
48. 	return false
49. }
