51. // SignJWT creates a signed JWT given a legalEntity and map of claims
52. func (client *Crypto) SignJWT(claims map[string]interface{}, kid string) (token string, err error) {
53. 	privateKey, err := client.Storage.GetPrivateKey(kid)
54. 	if err != nil {
55. 		if errors.Is(err, storage.ErrNotFound) {
56. 			return "", ErrKeyNotFound
57. 		}
58. 		return "", err
59. 	}
60. 	key, err := jwkKey(privateKey)
61. 	if err != nil {
62. 		return "", err
63. 	}
64. 
65. 	if err = key.Set(jwk.KeyIDKey, kid); err != nil {
66. 		return "", err
67. 	}
68. 
69. 	token, err = SignJWT(key, claims, nil)
70. 	return
71. }
72. 
73. func jwkKey(signer crypto.Signer) (key jwk.Key, err error) {
74. 	key, err = jwk.New(signer)
75. 	if err != nil {
76. 		return nil, err
77. 	}
78. 
79. 	switch signer.(type) {
80. 	case *rsa.PrivateKey:
81. 		key.Set(jwk.AlgorithmKey, jwa.PS256)
82. 	case *ecdsa.PrivateKey:
83. 		ecKey := signer.(*ecdsa.PrivateKey)
84. 		var alg jwa.SignatureAlgorithm
85. 		alg, err = ecAlg(ecKey)
86. 		key.Set(jwk.AlgorithmKey, alg)
87. 	default:
88. 		err = errors.New("unsupported signing private key")
89. 	}
90. 	return
91. }
92. 
93. // SignJWT signs claims with the signer and returns the compacted token. The headers param can be used to add additional headers
94. func SignJWT(key jwk.Key, claims map[string]interface{}, headers map[string]interface{}) (token string, err error) {
95. 	var sig []byte
96. 	t := jwt.New()
97. 
98. 	for k, v := range claims {
99. 		if err := t.Set(k, v); err != nil {
100. 			return "", err
101. 		}
102. 	}
103. 	hdr := convertHeaders(headers)
104. 
105. 	sig, err = jwt.Sign(t, jwa.SignatureAlgorithm(key.Algorithm()), key, jws.WithHeaders(hdr))
106. 	token = string(sig)
107. 
108. 	return
109. }
110. 
111. // JWTKidAlg parses a JWT, does not validate it and returns the 'kid' and 'alg' headers
112. func JWTKidAlg(tokenString string) (string, jwa.SignatureAlgorithm, error) {
113. 	j, err := jws.ParseString(tokenString)
114. 	if err != nil {
115. 		return "", "", err
116. 	}
117. 
118. 	if len(j.Signatures()) != 1 {
119. 		return "", "", errors.New("incorrect number of signatures in JWT")
120. 	}
121. 
122. 	sig := j.Signatures()[0]
123. 	hdrs := sig.ProtectedHeaders()
124. 	return hdrs.KeyID(), hdrs.Algorithm(), nil
125. }
126. 
127. // PublicKeyFunc defines a function that resolves a public key based on a kid
128. type PublicKeyFunc func(kid string) (crypto.PublicKey, error)
129. 
130. // ParseJWT parses a token, validates and verifies it.
131. func ParseJWT(tokenString string, f PublicKeyFunc) (jwt.Token, error) {
132. 	kid, alg, err := JWTKidAlg(tokenString)
133. 	if err != nil {
134. 		return nil, err
135. 	}
136. 
137. 	key, err := f(kid)
138. 	if err != nil {
139. 		return nil, err
140. 	}
141. 
142. 	if !isAlgorithmSupported(alg) {
143. 		return nil, fmt.Errorf("token signing algorithm is not supported: %s", alg)
144. 	}
145. 
146. 	return jwt.ParseString(tokenString, jwt.WithVerify(alg, key), jwt.WithValidate(true))
147. }
