149. func SignJWS(payload []byte, protectedHeaders map[string]interface{}, privateKey crypto.Signer) (string, error) {
150. 	headers := jws.NewHeaders()
151. 	for key, value := range protectedHeaders {
152. 		if err := headers.Set(key, value); err != nil {
153. 			return "", fmt.Errorf("unable to set header %s: %w", key, err)
154. 		}
155. 	}
156. 	privateKeyAsJWK, err := jwkKey(privateKey)
157. 	if err != nil {
158. 		return "", err
159. 	}
160. 	// The JWX library is fine with creating a JWK for a private key (including the private exponents), so
161. 	// we want to make sure the `jwk` header (if present) does not (accidentally) contain a private key.
162. 	// That would lead to the node leaking its private key material in the resulting JWS which would be very, very bad.
163. 	if headers.JWK() != nil {
164. 		var jwkAsPrivateKey crypto.Signer
165. 		if err := headers.JWK().Raw(&jwkAsPrivateKey); err == nil {
166. 			// `err != nil` is good in this case, because that means the key is not assignable to crypto.Signer,
167. 			// which is the interface implemented by all private key types.
168. 			return "", errors.New("refusing to sign JWS with private key in JWK header")
169. 		}
170. 	}
171. 	algo := jwa.SignatureAlgorithm(privateKeyAsJWK.Algorithm())
172. 	data, err := jws.Sign(payload, algo, privateKey, jws.WithHeaders(headers))
173. 	if err != nil {
174. 		return "", fmt.Errorf("unable to sign JWS %w", err)
175. 	}
176. 	return string(data), nil
177. }
178. 
179. func convertHeaders(headers map[string]interface{}) (hdr jws.Headers) {
180. 	hdr = jws.NewHeaders()
181. 
182. 	if headers != nil {
183. 		for k, v := range headers {
184. 			hdr.Set(k, v)
185. 		}
186. 	}
187. 	return
188. }
