190. func ecAlg(key *ecdsa.PrivateKey) (alg jwa.SignatureAlgorithm, err error) {
191. 	alg, err = ecAlgUsingPublicKey(key.PublicKey)
192. 	return
193. }
194. 
195. func ecAlgUsingPublicKey(key ecdsa.PublicKey) (alg jwa.SignatureAlgorithm, err error) {
196. 	switch key.Params().BitSize {
197. 	case 256:
198. 		alg = jwa.ES256
199. 	case 384:
200. 		alg = jwa.ES384
201. 	case 521:
202. 		alg = jwa.ES512
203. 	default:
204. 		err = ErrUnsupportedSigningKey
205. 	}
206. 	return
207. }
208. 
209. // SignatureAlgorithm determines the jwa.SigningAlgorithm for ec/rsa/ed25519 keys.
210. func SignatureAlgorithm(key crypto.PublicKey) (jwa.SignatureAlgorithm, error) {
211. 	if key == nil {
212. 		return "", errors.New("no key provided")
213. 	}
214. 
215. 	var ptr interface{}
216. 	switch v := key.(type) {
217. 	case rsa.PrivateKey:
218. 		ptr = &v
219. 	case rsa.PublicKey:
220. 		ptr = &v
221. 	case ecdsa.PrivateKey:
222. 		ptr = &v
223. 	case ecdsa.PublicKey:
224. 		ptr = &v
225. 	default:
226. 		ptr = v
227. 	}
228. 
229. 	switch ptr.(type) {
230. 	case *rsa.PrivateKey:
231. 		return jwa.PS256, nil
232. 	case *rsa.PublicKey:
233. 		return jwa.PS256, nil
234. 	case *ecdsa.PrivateKey:
235. 		sk := ptr.(*ecdsa.PrivateKey)
236. 		return ecAlgUsingPublicKey(sk.PublicKey)
237. 	case *ecdsa.PublicKey:
238. 		pk := ptr.(*ecdsa.PublicKey)
239. 		return ecAlgUsingPublicKey(*pk)
240. 	case ed25519.PrivateKey:
241. 		return jwa.EdDSA, nil
242. 	case ed25519.PublicKey:
243. 		return jwa.EdDSA, nil
244. 	default:
245. 		return "", fmt.Errorf(`invalid key type '%T' for jwk.New`, key)
246. 	}
247. }
