249. // Thumbprint generates a Nuts compatible thumbprint: Base58(SHA256(rfc7638-json))
250. func Thumbprint(key jwk.Key) (string, error) {
251. 	pkHash, err := key.Thumbprint(crypto.SHA256)
252. 	if err != nil {
253. 		return "", err
254. 	}
255. 	return base58.Encode(pkHash[:], base58.BitcoinAlphabet), nil
